'use strict';
let operatingFilter='all';
const operatingLabels={running:'Rodando',stopped:'Parado',workshop:'No mecânico',unknown:'Não informado'};
const cleaningLabels={complete:'Completa',external:'Externa',internal:'Interna',other:'Outra'};
const opsButton=(action,label,id,primary=false,extra='')=>`<button type="button" class="${primary?'primary':''}" data-ops-action="${action}" data-id="${esc(id)}" ${extra}>${esc(label)}</button>`;
const opsSelect=(name,label,options,value,required=true)=>`<label>${esc(label)}<select name="${name}" ${required?'required':''}>${options.map(([key,label])=>`<option value="${esc(key)}" ${key===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;
const opsArea=(name,label,value='',required=false,max=1000)=>`<label class="full">${esc(label)}<textarea name="${name}" rows="3" maxlength="${max}" ${required?'required':''}>${esc(value)}</textarea></label>`;
function operatingBadge(v){const status=v.operating?.status||'unknown';return `<span class="operating-badge operating-${esc(status)}">${esc(operatingLabels[status]||operatingLabels.unknown)}</span>`}
function operationalFilterControl(){return `<label class="operating-filter"><span>Operação</span><select id="operating-filter">${[['all','Todas as situações'],...Object.entries(operatingLabels)].map(([key,label])=>`<option value="${key}" ${operatingFilter===key?'selected':''}>${label}${key==='all'?'':' ('+state.vehicles.filter(v=>(v.operating?.status||'unknown')===key).length+')'}</option>`).join('')}</select></label>`}
function tollLabel(v){return v.toll?.present==='yes'?'Possui · '+v.toll.provider:v.toll?.present==='no'?'Não possui':'Não informado'}
function operationalOverview(v){const open=(v.issues||[]).filter(i=>i.status==='open');return `<div class="operational-overview"><section class="panel"><div class="section-head"><h2>Situação de operação</h2>${opsButton('operating','Atualizar situação',v.id)}</div>${operatingBadge(v)}${v.operating?`<p class="help">Desde ${fmt(v.operating.since)}${v.operating.location?' · '+esc(v.operating.location):''}</p>${v.operating.notes?`<p class="operating-note">${esc(v.operating.notes)}</p>`:''}`:'<p class="help">Informe se o veículo está rodando, parado ou no mecânico.</p>'}<p class="help">${open.length?`${open.length} problema(s) em aberto.`:'Nenhum problema registrado em aberto.'}</p>${opsButton('issue-add','Relatar problema',v.id)}</section><section class="panel"><h2>Uso do veículo</h2><dl class="facts"><div><dt>Capacidade veicular</dt><dd>${capacityText(v)}</dd></div><div><dt>Pedágio automático</dt><dd>${esc(tollLabel(v))}</dd></div></dl><div class="actions">${opsButton('capacity',v.capacity?'Atualizar capacidade':'Confirmar capacidade',v.id)}${opsButton('cleaning-add','Registrar limpeza',v.id)}</div><p class="help">Pedágio e registros de limpeza estão na aba Rotina.</p></section></div>`}
function editOperating(v){const old=v.operating||{};modal('Situação de operação',v.plate+' · Como o veículo está agora?',opsSelect('status','Situação',[['','Escolha a situação'],['running','Rodando'],['stopped','Parado'],['workshop','No mecânico']],old.status||'')+field('since','Desde quando','date',old.since?.slice(0,10)||dateOnly(),`required max="${dateOnly()}"`)+field('location','Local / oficina (opcional)','text',old.location||'','maxlength="150"',true)+opsArea('notes','Motivo e observações',old.notes||''),f=>{v.operating={status:f.get('status'),since:f.get('since'),location:f.get('location').trim(),notes:f.get('notes').trim()};if(v.operating.since>dateOnly())throw Error('A data não pode estar no futuro.');log(v,'Situação: '+operatingLabels[v.operating.status]+(v.operating.location?' · '+v.operating.location:'')+(v.operating.notes?' · '+v.operating.notes:''));commit('Situação atualizada para toda a frota.')})}
function issuesView(v){const all=v.issues||[],open=all.filter(i=>i.status==='open'),resolved=all.filter(i=>i.status==='resolved').sort((a,b)=>b.resolvedOn.localeCompare(a.resolvedOn));const row=i=>`<article class="issue-entry"><div class="section-head"><div><strong>${esc(i.title)}</strong><p class="help">${fmt(i.date)}${i.recordedBy?.name||i.actorName?' · '+esc(i.recordedBy?.name||i.actorName):''}</p></div>${badge(i.status==='resolved'?'green':i.severity==='urgent'?'red':'yellow',i.status==='resolved'?'Resolvido':i.severity==='urgent'?'Urgente':'Atenção')}</div><p class="entry-note">${esc(i.description||'Sem observações adicionais.')}</p>${i.status==='open'?opsButton('issue-resolve','Registrar resolução',v.id,false,`data-issue="${esc(i.id)}"`):`<p class="help">Resolvido em ${fmt(i.resolvedOn)}${i.resolvedBy?.name?' · '+esc(i.resolvedBy.name):''}</p><p class="entry-note">${esc(i.resolution)}</p>`}</article>`;return `<section class="panel"><div class="section-head"><div><h2>Problemas do veículo</h2><p class="help">${open.length} em aberto · ${resolved.length} resolvido(s)</p></div>${opsButton('issue-add','Relatar problema',v.id,true)}</div>${open.map(row).join('')||'<p class="help">Nenhum problema registrado em aberto. Relate falhas, barulhos ou funcionamento irregular aqui.</p>'}${resolved.length?`<details><summary>Problemas resolvidos (${resolved.length})</summary>${resolved.map(row).join('')}</details>`:''}</section>`}
function reportIssue(v){modal('Relatar problema',v.plate+' · Descreva o que está acontecendo.',field('title','Problema','text','','required maxlength="120" placeholder="Ex.: Motor apaga durante o trajeto"',true)+opsArea('description','Detalhes do problema','',false,2000)+opsSelect('severity','Prioridade',[['attention','Atenção'],['urgent','Urgente']],'attention')+field('date','Quando foi observado','datetime-local',localNow(),`required max="${localNow()}"`)+opsSelect('operating','Situação do veículo',[['keep','Manter situação atual'],['stopped','Atualizar para parado'],['workshop','Atualizar para no mecânico']],'keep'),f=>{if(f.get('date')>localNow())throw Error('A data não pode estar no futuro.');const title=f.get('title').trim();if(!title)throw Error('Descreva o problema.');const person=currentProfile();(v.issues||=[]).push({id:uid(),date:f.get('date'),title,description:f.get('description').trim(),severity:f.get('severity'),status:'open',actorId:person.id,actorName:person.name});if(f.get('operating')!=='keep')v.operating={status:f.get('operating'),since:f.get('date').slice(0,10),location:v.operating?.location||'',notes:title};log(v,'Problema relatado: '+title+' · '+(f.get('severity')==='urgent'?'Urgente':'Atenção')+(f.get('operating')!=='keep'?' · Situação: '+operatingLabels[f.get('operating')]:''));commit('Problema registrado e incluído nos alertas.')},'Registrar problema')}
function resolveIssue(v,id){const issue=(v.issues||[]).find(i=>i.id===id);if(!issue||issue.status!=='open')return;modal('Registrar resolução',v.plate+' · '+issue.title,field('date','Data da resolução','date',dateOnly(),`required min="${issue.date.slice(0,10)}" max="${dateOnly()}"`,true)+opsArea('resolution','O que foi feito?','',true,2000)+'<p class="help full">Depois, atualize a situação de operação se o veículo voltou a rodar.</p>',f=>{const date=f.get('date'),resolution=f.get('resolution').trim();if(date<issue.date.slice(0,10)||date>dateOnly()||!resolution)throw Error('Confira a data e informe o que foi feito.');issue.status='resolved';issue.resolvedOn=date;issue.resolution=resolution;issue.resolvedBy={id:currentProfile().id,name:currentProfile().name};log(v,'Problema resolvido: '+issue.title+' · '+resolution,date);commit('Resolução registrada. Histórico preservado.')},'Registrar resolução')}
function editToll(v){const t=v.toll||{};modal('Pedágio automático',v.plate+' · Informe a tag usada no veículo.',opsSelect('present','Tem pedágio automático?',[['unknown','Ainda não informado'],['yes','Sim'],['no','Não']],t.present||'unknown')+field('provider','Operadora','text',t.provider||'','maxlength="80" list="toll-providers" placeholder="Ex.: ConectCar ou Sem Parar"')+'<datalist id="toll-providers"><option value="ConectCar"><option value="Sem Parar"><option value="Veloe"><option value="Move Mais"></datalist>'+opsArea('notes','Observações (opcional)',t.notes||'',false,500),f=>{const present=f.get('present'),provider=present==='yes'?f.get('provider').trim():'';if(present==='yes'&&!provider)throw Error('Informe a operadora da tag.');v.toll={present,provider,notes:f.get('notes').trim()};log(v,'Pedágio automático: '+tollLabel(v)+(t.provider&&t.provider!==provider?' · Operadora anterior: '+t.provider:''));commit('Pedágio automático atualizado.')});const form=document.getElementById('modal-form');const sync=()=>{const yes=form.elements.present.value==='yes';form.elements.provider.disabled=!yes;form.elements.provider.required=yes};form.elements.present.addEventListener('change',sync);sync()}
function editCapacity(v){modal('Capacidade veicular',v.plate+' · Confira a quantidade atual de lugares no documento.',field('capacity','Capacidade atual (lugares)','number',v.capacity||'','required min="1" max="200" step="1"',true)+opsArea('notes','Observações (opcional)',v.capacityNote||'',false,500)+'<p class="help full">Informe a quantidade de lugares confirmada para a configuração atual do veículo.</p>',f=>{const capacity=Number(f.get('capacity'));if(!Number.isInteger(capacity)||capacity<1||capacity>200)throw Error('Informe uma quantidade válida de lugares.');const previous=v.capacity;v.capacity=capacity;v.capacitySource={kind:'user',status:'confirmed',confirmedOn:dateOnly(),profileId:currentProfile().id,profileName:currentProfile().name};v.capacityNote=f.get('notes').trim();log(v,'Capacidade confirmada: '+capacity+' lugares'+(previous?' · Anterior: '+previous+' lugares':'')+(v.capacityNote?' · '+v.capacityNote:''));commit('Capacidade atualizada.')})}
function addCleaning(v){modal('Registrar limpeza',v.plate+' · Registre a limpeza realizada.',field('date','Data e hora','datetime-local',localNow(),`required max="${localNow()}"`)+opsSelect('type','Tipo de limpeza',Object.entries(cleaningLabels),'complete')+field('performedBy','Quem levou / acompanhou','text',currentProfile()?.name||'','required maxlength="150"',true)+field('place','Local (opcional)','text','','maxlength="150"')+field('cost','Valor pago (opcional)','number','','min="0" step="0.01"')+opsArea('notes','Observações (opcional)'),f=>{if(f.get('date')>localNow())throw Error('A data não pode estar no futuro.');const person=currentProfile(),cost=f.get('cost')===''?null:Number(f.get('cost')),performedBy=f.get('performedBy').trim();if((cost!==null&&(!Number.isFinite(cost)||cost<0))||!performedBy)throw Error('Confira o valor e quem acompanhou a limpeza.');(v.cleanings||=[]).push({id:uid(),date:f.get('date'),type:f.get('type'),performedBy,place:f.get('place').trim(),cost,notes:f.get('notes').trim(),actorId:person.id,actorName:person.name});log(v,'Limpeza '+cleaningLabels[f.get('type')].toLowerCase()+' · '+performedBy+(cost!==null?' · '+money(cost):''),f.get('date').slice(0,10));commit('Limpeza registrada para todos os aparelhos.')},'Registrar limpeza')}
function routineView(v){const list=[...(v.cleanings||[])].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="operational-overview"><section class="panel"><div class="section-head"><h2>Pedágio automático</h2>${opsButton('toll','Atualizar',v.id)}</div><p>${esc(tollLabel(v))}</p>${v.toll?.notes?`<p class="entry-note">${esc(v.toll.notes)}</p>`:''}</section><section class="panel"><div class="section-head"><h2>Capacidade veicular</h2>${opsButton('capacity','Confirmar capacidade',v.id)}</div><p class="capacity-value">${capacityText(v)}</p>${capacityResearchNote(v)}${v.capacityNote?`<p class="entry-note">${esc(v.capacityNote)}</p>`:'<p class="help">Quantidade de lugares da configuração atual.</p>'}</section></div><section class="panel"><div class="section-head"><div><h2>Limpezas</h2><p class="help">${list.length} registro(s)${list[0]?' · Última em '+fmt(list[0].date):''}</p></div>${opsButton('cleaning-add','Registrar limpeza',v.id,true)}</div>${list.map(e=>`<article class="cleaning-entry"><div class="section-head"><strong>${fmt(e.date)} · ${esc(cleaningLabels[e.type])}</strong><span>${e.cost===null?'Valor não informado':money(e.cost)}</span></div><p>${esc(e.performedBy)}${e.place?' · '+esc(e.place):''}</p>${e.notes?`<p class="entry-note">${esc(e.notes)}</p>`:''}<p class="help">Registrado por ${esc(e.recordedBy?.name||e.actorName||'perfil não informado')}${e.date.includes('T')?' · '+esc(e.date.slice(11,16)):''}</p></article>`).join('')||'<p class="help">Nenhuma limpeza registrada. Informe quem levou o veículo, o tipo de limpeza e a data.</p>'}</section>`}
function fipeView(v){const f=v.fipe,stale=f&&f.referenceKey!==dateOnly().slice(0,7);return `<section class="panel fipe-panel"><div class="section-head"><div><h2>Referência FIPE</h2><p class="help">${f?'Código '+esc(f.code)+' · '+esc(f.model)+' · '+esc(f.modelYear):'Vincule a versão exata para acompanhar o valor mensal.'}</p></div>${opsButton('fipe-link',f?'Alterar versão':'Vincular versão FIPE',v.id)}</div>${f?`<div class="fipe-value">${esc(f.price||'Valor indisponível')}</div><p>Referência: <strong>${esc(f.referenceMonth)}</strong>${stale?' · <span class="fipe-stale">Referência anterior</span>':''}</p><p class="help">Consultado em ${fmt(f.checkedAt)} · FIPE API / Parallelum.</p>${f.lastError?`<p class="rule-note">${esc(f.lastError)} O último valor consultado foi preservado.</p>`:''}<div class="actions">${opsButton('fipe-refresh','Consultar atualização',v.id)}${opsButton('fipe-unlink','Remover vínculo',v.id)}</div>`:'<p class="help">Há modelos e implementos sem correspondência na tabela. Nenhum valor é estimado sem um vínculo confirmado.</p>'}<p class="help">Atualização mensal no dia 1º, com o PC ligado e acesso à internet. Se estiver desligado, a consulta é feita ao iniciar. Preço médio de referência; a configuração do veículo pode influenciar o valor real.</p></section>`}
function capacityText(v){return v.capacity?num(v.capacity)+' lugares'+(v.capacitySource?.status==='reference'?' · pesquisado':''):'Não informada'}
function capacityResearchNote(v){return v.capacitySource?.status==='reference'?'<p class="help">'+esc(v.capacitySource.note||'Lotação de consulta pública. Confirme a configuração atual.')+'</p>':''}
function technicalSpecsView(v){const t=v.technicalSpecs;if(!t)return '';const rows=[['Fabricante',t.manufacturer],['Modelo registrado na consulta',t.registeredModel],['Origem',t.origin],['Potência',t.enginePowerCv?num(t.enginePowerCv)+' cv':''],['Cilindrada',t.engineDisplacementCc?num(t.engineDisplacementCc)+' cm³':''],['Modelo do motor',t.engineModel],['Transmissão',t.transmission],['Torque máximo',t.engineTorqueNm?num(t.engineTorqueNm)+' Nm':''],['Tipo registrado',t.registeredType],['Espécie registrada',t.registeredSpecies],['Carroceria registrada',t.registeredBody]].filter(([,value])=>value);const sources=[...new Set(Object.values(t.sources||{}).map(s=>s.url).filter(url=>String(url).startsWith('https://')))];return '<section class="panel"><h2>Ficha técnica pesquisada</h2><p class="help">Dados da consulta da placa e das especificações da versão. Adaptações podem alterar a configuração atual.</p><dl class="facts">'+rows.map(([label,value])=>'<div><dt>'+esc(label)+'</dt><dd>'+esc(value)+'</dd></div>').join('')+'</dl><details><summary>Fontes das especificações</summary><div class="research-links">'+sources.map((url,index)=>'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">Fonte '+(index+1)+'</a>').join('')+'</div></details></section>'}
const normalizeFipe=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
async function openFipe(v){if(pendingChanges)throw Error('Salve as alterações pendentes antes de vincular a FIPE.');const selectedFipe=v.fipe||{};modal('Vincular versão FIPE',v.plate+' · Escolha a versão que consta no documento.',opsSelect('type','Tabela',[['cars','Carros e utilitários'],['trucks','Caminhões e micro-ônibus'],['motorcycles','Motos']],selectedFipe.type||(v.category==='Carga'||v.category==='Transporte'?'trucks':'cars'))+opsSelect('brand','Marca',[['','Carregando marcas…']],'')+field('modelSearch','Filtrar versões (opcional)','text','','maxlength="100" placeholder="Ex.: Sprinter, Master, EcoSport"',true)+opsSelect('model','Versão exata',[['','Escolha uma marca']],'')+opsSelect('year','Ano/modelo e combustível',[['','Escolha uma versão']],'')+'<p class="help full" id="fipe-preview" role="status">Carregando as opções da tabela…</p><p class="help full">O vínculo não altera modelo, combustível ou ano do cadastro. Para micro-ônibus, confira se a referência corresponde ao veículo completo ou ao chassi.</p>',async(f,form)=>{const choice={type:f.get('type'),brandId:f.get('brand'),modelId:f.get('model'),yearId:f.get('year')};if(form.dataset.ready!==Object.values(choice).join('/'))throw Error('Selecione a versão e aguarde a consulta do valor.');await fipeMutation('/api/fipe/link',{vehicleId:v.id,selection:choice},'Versão FIPE vinculada.')},'Confirmar vínculo');
 const form=document.getElementById('modal-form'),preview=document.getElementById('fipe-preview');let generation=0,models=[];const controls=form.elements;const setOptions=(control,options,placeholder,value='')=>{control.innerHTML='<option value="">'+esc(placeholder)+'</option>'+options.map(e=>`<option value="${esc(e.code)}" ${String(e.code)===String(value)?'selected':''}>${esc(e.name)}</option>`).join('')};const valid=token=>token===generation&&form.isConnected;const clearReady=()=>{form.dataset.ready='';form.querySelector('[type="submit"]').disabled=true};
 async function loadQuote(){const token=++generation;clearReady();if(!controls.year.value)return;const choice={type:controls.type.value,brandId:controls.brand.value,modelId:controls.model.value,yearId:controls.year.value};preview.textContent='Consultando valor…';try{const detail=await requestShared('/api/fipe/quote?'+new URLSearchParams(choice));if(!valid(token))return;preview.textContent=detail.price+' · '+detail.referenceMonth+' · Código '+detail.code;form.dataset.ready=Object.values(choice).join('/');form.querySelector('[type="submit"]').disabled=false}catch(e){if(valid(token))preview.textContent=e.message}}
 async function loadYears(){const token=++generation;clearReady();setOptions(controls.year,[],'Carregando anos…');if(!controls.model.value)return;try{const all=await requestShared('/api/fipe/catalog?path='+encodeURIComponent(controls.type.value+'/brands/'+controls.brand.value+'/models/'+controls.model.value+'/years'));if(!valid(token))return;const years=all.filter(e=>!v.year||Number(e.code.split('-')[0])===Number(v.year));setOptions(controls.year,years,years.length?'Escolha ano e combustível':'Ano '+v.year+' não disponível para esta versão',selectedFipe.yearId);preview.textContent=years.length?'Confira a versão e escolha o ano/modelo.':'O ano/modelo do cadastro não está disponível nesta versão.';if(controls.year.value)await loadQuote()}catch(e){if(valid(token))preview.textContent=e.message}}
 function filterModels(){const term=normalizeFipe(controls.modelSearch.value);const filtered=models.filter(m=>normalizeFipe(m.name).includes(term));setOptions(controls.model,filtered,'Escolha a versão exata',selectedFipe.modelId);setOptions(controls.year,[],'Escolha uma versão');clearReady()}
 async function loadModels(){const token=++generation;clearReady();setOptions(controls.model,[],'Carregando versões…');setOptions(controls.year,[],'Escolha uma versão');if(!controls.brand.value)return;try{models=await requestShared('/api/fipe/catalog?path='+encodeURIComponent(controls.type.value+'/brands/'+controls.brand.value+'/models'));if(!valid(token))return;filterModels();preview.textContent='Escolha a versão exata do veículo.';if(controls.model.value)await loadYears()}catch(e){if(valid(token))preview.textContent=e.message}}
 async function loadBrands(){const token=++generation;clearReady();setOptions(controls.brand,[],'Carregando marcas…');setOptions(controls.model,[],'Escolha uma marca');setOptions(controls.year,[],'Escolha uma versão');try{const brands=await requestShared('/api/fipe/catalog?path='+controls.type.value+'/brands');if(!valid(token))return;const source=v.publicResearch?.referenceOnly?.plateLookup?.fields?.Marca||v.model.split('/')[0];let match=brands.find(b=>normalizeFipe(b.name)===normalizeFipe(source));if(!match&&/m\.benz|mercedes/i.test(source))match=brands.find(b=>/mercedes/i.test(b.name));setOptions(controls.brand,brands,'Escolha a marca',selectedFipe.type===controls.type.value?selectedFipe.brandId:match?.code);preview.textContent='Escolha a marca e a versão.';if(controls.brand.value)await loadModels()}catch(e){if(valid(token))preview.textContent=e.message}}
 controls.type.addEventListener('change',loadBrands);controls.brand.addEventListener('change',loadModels);controls.model.addEventListener('change',loadYears);controls.year.addEventListener('change',loadQuote);controls.modelSearch.addEventListener('input',()=>{generation++;filterModels();preview.textContent='Escolha a versão exata do veículo.'});await loadBrands();
}
async function fipeMutation(url,input,message){if(pendingChanges||saving)throw Error('Aguarde salvar as alterações antes de consultar a FIPE.');const snapshot=await requestShared(url,{method:'POST',headers:{'Content-Type':'application/json','X-Alinho-Profile':activeProfileId||''},body:JSON.stringify(input)});if(pendingChanges)return;adoptShared(snapshot);closeModal();shell();toast(message)}
document.addEventListener('click',e=>{const button=e.target.closest('[data-ops-action]');if(!button||saving)return;if(!requireActiveProfile())return;const v=getV(button.dataset.id);if(!v)return;try{let result;switch(button.dataset.opsAction){case'operating':return editOperating(v);case'issue-add':return reportIssue(v);case'issue-resolve':return resolveIssue(v,button.dataset.issue);case'toll':return editToll(v);case'capacity':return editCapacity(v);case'cleaning-add':return addCleaning(v);case'fipe-link':result=openFipe(v);break;case'fipe-refresh':button.disabled=true;result=fipeMutation('/api/fipe/refresh',{vehicleId:v.id},'Consulta FIPE concluída. Confira o mês de referência.').finally(()=>button.disabled=false);break;case'fipe-unlink':return modal('Remover vínculo FIPE',v.plate,`<p class="full">O valor deixará de aparecer neste veículo. Você pode vincular a versão novamente quando quiser.</p>`,()=>fipeMutation('/api/fipe/unlink',{vehicleId:v.id},'Vínculo FIPE removido.'),'Remover vínculo')}if(result?.catch)result.catch(e=>toast(e.message))}catch(e){toast(e.message)}});
